# ================================================================ OA 20 · clase 3
L(OA20, 3,
  "Este cuaderno, lápiz y una hoja. Las locuciones con su significado vienen escritas.",
  "Aprenderé a reconocer y usar locuciones: grupos de palabras con un significado fijo. Sirve para decir un mensaje de manera más expresiva y para entender lo que otros dicen.",
  ["Sé usar sinónimos e hiperónimos.", "Sé la diferencia entre sentido literal y figurado."],
  ["Una locución es un grupo de palabras que funcionan juntas con un significado fijo. Su sentido no se obtiene sumando el significado de cada palabra. «Estar en las nubes» no significa estar sobre las nubes, sino estar distraído. Por eso se dice que tiene sentido figurado.",
   "Hay locuciones adverbiales, que dicen cómo, cuándo o dónde ocurre algo: «a menudo» (con frecuencia), «de repente» (sin aviso), «a oscuras» (sin luz), «en vano» (sin lograr el resultado). Hay locuciones verbales, que reemplazan a un verbo: «echar una mano» (ayudar), «meter la pata» (equivocarse), «tomar el pelo» (burlarse de alguien), «costar un ojo de la cara» (ser muy caro), «poner el grito en el cielo» (protestar con fuerza).",
   "Las locuciones sirven para decir un mismo mensaje de otra manera: «Me ayudó» se transforma en «Me echó una mano». Pero algunas son informales y no sirven en un texto muy formal. Si quieres usarlas, aprende su significado exacto y no cambies las palabras que las forman."],
  [("locución", "grupo de palabras con significado fijo"), ("sentido figurado", "significado que no es el literal"), ("locución adverbial", "locución que indica cómo, cuándo o dónde"), ("locución verbal", "locución que funciona como un verbo"), ("informal", "propio de una conversación entre cercanos"), ("literal", "que se entiende tal como suena")],
  [("Reconocer el significado figurado", "«Lucía estaba en las nubes durante la clase». ¿Qué significa?", ["Si fuera literal, Lucía estaría sobre las nubes.", "Es una locución verbal.", "Significa estar distraída."], "Estaba distraída."),
   ("Reescribir con locución", "Reescribe con una locución: «Camilo me ayudó con la mochila».", ["«Ayudar» se dice «echar una mano».", "Conservo el tiempo verbal.", "Lo escribo de nuevo."], "«Camilo me echó una mano con la mochila».")],
  [("Entender una locución en sentido literal.", "Se pierde el mensaje real.", "Pregúntate si el sentido es figurado."),
   ("Cambiar una palabra de la locución.", "Pierde su significado fijo.", "Úsala tal como es.")],
  ([E("«Voy a la plaza a menudo.» ¿Qué significa «a menudo»: con frecuencia o nunca?", "Con frecuencia", "Indica que ocurre muchas veces."),
    E("«Entró de repente a la sala.» ¿Qué significa «de repente»: sin aviso o con lentitud?", "Sin aviso", "Indica algo inesperado."),
    E("«Subimos las escaleras a oscuras.» ¿Qué significa «a oscuras»: sin luz o con prisa?", "Sin luz", "Indica falta de luz.")],
   [E("¿Qué significa «meter la pata»: equivocarse o guardar un objeto?", "Equivocarse", "Es una locución verbal de sentido figurado."),
    E("¿Qué significa «costar un ojo de la cara»: ser muy caro o ser peligroso?", "Ser muy caro", "Se dice de algo con precio alto."),
    E("¿Qué es una locución: un grupo de palabras con significado fijo o una palabra con tilde?", "Un grupo de palabras con significado fijo", "No se explica sumando cada palabra.")],
   [E("«Nos tomó el pelo con esa broma.» ¿Qué significa: se burló o nos peinó?", "Se burló", "Es una locución verbal figurada."),
    E("Reemplaza con una locución: «Ayudé a mi vecino a cargar las bolsas». ¿Qué opción usa una locución? A: «Le eché una mano». B: «Le saqué la mano».", "A", "«Echar una mano» significa ayudar."),
    E("Completa con una locución adverbial: «Lo intenté ___, pero no logré abrir la caja». Opciones: en vano o a menudo.", "En vano", "Significa que no se logró el resultado.")],
   [E("Un compañero entiende «Está en las nubes» como «Está sobre las nubes». ¿Qué error comete?", "La entiende en sentido literal", "Es una locución de sentido figurado."),
    E("Alguien cambia «meter la pata» por «meter el pie». ¿Mantiene el significado?", "No", "Las locuciones no cambian sus palabras.")],
   [E("«Mi tío puso el grito en el cielo cuando vio la cuenta.» ¿Qué significa «poner el grito en el cielo»: protestar con fuerza o gritar de alegría?", "Protestar con fuerza", "Se usa para quejarse de manera exagerada."),
    E("En un informe formal para la directora, ¿conviene escribir «Los precios nos tomaron el pelo» o «Los precios fueron engañosos»?", "Los precios fueron engañosos", "La locución es informal.")]),
  [E("Quieres decir con una locución que un cuaderno nuevo es carísimo: «Ese cuaderno cuesta ___». ¿Qué completas: un ojo de la cara o un lápiz?", "Un ojo de la cara", "Indica un precio muy alto.")],
  [E("¿«Estar en las nubes» tiene sentido literal o figurado?", "Figurado", "Significa estar distraído."),
   E("¿«En vano» significa sin lograr el resultado?", "Sí", "Indica que el esfuerzo no sirvió."),
   E("¿Se puede cambiar una palabra dentro de una locución sin perder el significado?", "No", "Su significado es fijo.")],
  ("Escribe una historia de cuatro oraciones sobre un recreo en la que uses al menos tres locuciones de esta clase: a menudo, de repente, a oscuras, en vano, echar una mano, meter la pata, tomar el pelo, costar un ojo de la cara. Subraya las que usaste.",
   "«A menudo juego a la pelota en el patio. De repente, Tomás metió la pata y rompió la red. Intentamos arreglarla en vano. Entonces Ema nos echó una mano».",
   ["usa tres locuciones", "cada una con su significado correcto", "la historia es coherente"], ["historia con locuciones subrayadas"], ["usar una locución con otro significado", "cambiar sus palabras"],
   "Pide explicar con otras palabras lo que significa cada locución."),
  "Pregunta a una persona de tu casa una locución que use y anota su significado.",
  "Escribe tres locuciones con su significado literal y su significado figurado.")

